WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_summarize_problem'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '概括问题', 'kp-sl-summarize-problem', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "归纳概括：问题类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "问题 = 坏现象。寻找带有贬义色彩的词汇。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找词雷达"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到概括问题题，拿着笔在材料里疯狂扫描以下字眼："}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "缺乏、匮乏、不足、不到位、落后、滞后。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乱象、严重、恶化、下降、萎缩。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "难、贵、慢、少。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题格式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "标准格式：核心词汇 + 具体表现。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "例如：“基础设施落后。道路坑洼不平，且缺乏路灯照明。”（如果字数不够，只写“基础设施落后”即可得分）。"}]}]}$$ AS jsonb), NULL, '概括问题的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "归纳概括", "概括问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_summarize_problem", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
